class Solution {
public:
 int minimumRefill(vector<int>& plants,int capacityA,int capacityB){
  int i=0,j=(int)plants.size()-1,a=capacityA,b=capacityB,ans=0;
  while(i<j){
   if(a<plants[i]){++ans;a=capacityA;}a-=plants[i++];
   if(b<plants[j]){++ans;b=capacityB;}b-=plants[j--];
  }
  if(i==j && max(a,b)<plants[i])++ans;return ans;
 }
};
